import React, { useRef } from "react";
import { motion, useInView } from "framer-motion";

const PHOTO_B64 = "";

// ── Animated CGPA bar ─────────────────────────────────────────────────────────
function CGPACard({ semester, score, max = 10, delay, best, awaited }) {
  const ref = useRef(null);
  const inView = useInView(ref, { once: true, margin: "-60px" });
  const pct = awaited ? 0 : (score / max) * 100;

  return (
    <motion.div
      ref={ref}
      className={`cgpa-card ${best ? "cgpa-best" : ""} ${awaited ? "cgpa-awaited" : ""}`}
      initial={{ opacity: 0, y: 20 }}
      animate={inView ? { opacity: 1, y: 0 } : {}}
      transition={{ delay, duration: 0.5, ease: [0.22, 1, 0.36, 1] }}
    >
      {best && <span className="cgpa-badge">Best ↑</span>}
      {awaited && <span className="cgpa-badge cgpa-badge--pending">Results Awaited</span>}
      <div className="cgpa-header">
        <span className="cgpa-sem">{semester}</span>
        <span className={`cgpa-score ${awaited ? "cgpa-score--dim" : ""}`}>
          {awaited ? "—" : score}
        </span>
      </div>
      <div className="cgpa-track">
        <motion.div
          className={`cgpa-fill ${awaited ? "cgpa-fill--dash" : ""}`}
          initial={{ width: 0 }}
          animate={inView ? { width: `${awaited ? 100 : pct}%` } : {}}
          transition={{ delay: delay + 0.2, duration: 1, ease: "easeOut" }}
        />
      </div>
      {!awaited && <span className="cgpa-out">/ {max}.00 SGPA</span>}
    </motion.div>
  );
}

// ── Detail row ────────────────────────────────────────────────────────────────
function DetailRow({ icon, label, value, delay }) {
  const ref = useRef(null);
  const inView = useInView(ref, { once: true, margin: "-40px" });
  return (
    <motion.div
      ref={ref}
      className="detail-row"
      initial={{ opacity: 0, x: -16 }}
      animate={inView ? { opacity: 1, x: 0 } : {}}
      transition={{ delay, duration: 0.45 }}
    >
      <span className="detail-icon">{icon}</span>
      <span className="detail-label">{label}</span>
      <span className="detail-value">{value}</span>
    </motion.div>
  );
}

// ── Section heading ───────────────────────────────────────────────────────────
function SH({ children }) {
  const ref = useRef(null);
  const inView = useInView(ref, { once: true, margin: "-40px" });
  return (
    <motion.div ref={ref} className="sh-wrap"
      initial={{ opacity: 0, y: 14 }} animate={inView ? { opacity: 1, y: 0 } : {}}
      transition={{ duration: 0.45 }}>
      <span className="sh-line" /><h3 className="sh-text">{children}</h3>
    </motion.div>
  );
}

// ── Achievement pill ──────────────────────────────────────────────────────────
function AchievPill({ icon, title, desc, delay }) {
  const ref = useRef(null);
  const inView = useInView(ref, { once: true, margin: "-40px" });
  return (
    <motion.div ref={ref} className="achiev-pill"
      initial={{ opacity: 0, y: 18 }} animate={inView ? { opacity: 1, y: 0 } : {}}
      transition={{ delay, duration: 0.5 }}>
      <span className="achiev-icon">{icon}</span>
      <div className="achiev-body">
        <span className="achiev-title">{title}</span>
        <span className="achiev-desc">{desc}</span>
      </div>
    </motion.div>
  );
}

// ── Edu timeline entry ────────────────────────────────────────────────────────
function EduEntry({ icon, degree, institute, period, status, delay }) {
  const ref = useRef(null);
  const inView = useInView(ref, { once: true, margin: "-40px" });
  return (
    <motion.div ref={ref} className="edu-entry"
      initial={{ opacity: 0, x: -20 }} animate={inView ? { opacity: 1, x: 0 } : {}}
      transition={{ delay, duration: 0.5 }}>
      <div className="edu-icon">{icon}</div>
      <div className="edu-body">
        <span className="edu-degree">{degree}</span>
        <span className="edu-inst">{institute}</span>
        <div className="edu-footer">
          <span className="edu-period">{period}</span>
          {status && <span className="edu-status">{status}</span>}
        </div>
      </div>
    </motion.div>
  );
}

